const fs = require('fs');
const https = require('https');

const token = fs.readFileSync('/governance/.discord-token', 'utf8').trim();
const statePath = '/governance/shared/.n8n-severity-state.json';
const channelId = '1476794621903241357';

const CHANNELS = {
  'status-updates': '1476794554601574593',
  'severity-alerts': '1476794637762039808',
  'human-oversight': '1476794543897837662'
};

let lastId = '0';
try {
  const state = JSON.parse(fs.readFileSync(statePath, 'utf8'));
  lastId = state.lastMessageId || '0';
} catch(e) {}

const messages = await new Promise((resolve) => {
  const req = https.request({
    hostname: 'discord.com', path: `/api/v10/channels/${channelId}/messages?limit=10`, method: 'GET',
    headers: { 'Authorization': `Bot ${token}` }
  }, (res) => {
    let data = ''; res.on('data', c => data += c);
    res.on('end', () => { try { resolve(JSON.parse(data)); } catch(e) { resolve([]); } });
  });
  req.on('error', () => resolve([]));
  req.end();
});

if (!Array.isArray(messages) || messages.length === 0) {
  return [{ json: { routed: 0, processed: 0 } }];
}

const newMessages = messages.filter(m => m.id > lastId).reverse();
if (newMessages.length === 0) {
  return [{ json: { routed: 0, processed: 0 } }];
}

let routedCount = 0;

for (const msg of newMessages) {
  const content = (msg.content || '').toUpperCase();
  const author = msg.author?.username || 'unknown';
  let severity = 'INFO';

  if (content.includes('CRITICAL')) severity = 'CRITICAL';
  else if (content.includes('BLOCKED')) severity = 'BLOCKED';
  else if (content.includes('WARN')) severity = 'WARN';

  const targets = [];
  if (['WARN', 'BLOCKED', 'CRITICAL'].includes(severity)) targets.push('status-updates');
  if (['BLOCKED', 'CRITICAL'].includes(severity)) targets.push('severity-alerts');
  if (severity === 'CRITICAL') targets.push('human-oversight');

  if (targets.length === 0) continue;

  const prefix = severity === 'CRITICAL' ? '\u{1F534}' : severity === 'BLOCKED' ? '\u{1F6D1}' : '\u26A0\uFE0F';
  const routeMsg = `${prefix} **${severity}** \u2014 Routed from #review-verdicts\n**Author:** ${author} | **Time:** ${msg.timestamp}\n\n${(msg.content || '').substring(0, 1800)}`;

  for (const target of targets) {
    const body = JSON.stringify({ content: routeMsg });
    await new Promise((resolve) => {
      const req = https.request({
        hostname: 'discord.com', path: `/api/v10/channels/${CHANNELS[target]}/messages`, method: 'POST',
        headers: { 'Authorization': `Bot ${token}`, 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) }
      }, (res) => { let d = ''; res.on('data', c => d += c); res.on('end', () => resolve(d)); });
      req.write(body); req.end();
    });
    routedCount++;
  }
}

const newestId = newMessages[newMessages.length - 1]?.id || lastId;
try { fs.writeFileSync(statePath, JSON.stringify({ lastMessageId: newestId, updatedAt: new Date().toISOString() })); } catch(e) {}

return [{ json: { routed: routedCount, processed: newMessages.length } }];
